#include <bits/stdc++.h>
using namespace std;

long long fact(int n) {
    long long ans = 1;
    for (int i = 1; i <= n; i++) ans *= i;
    return ans;
}

long long C(int n, int m) {
    if (m < 0 || m > n) return 0;
    return fact(n) / fact(m) / fact(n - m);
}

int main() {
    cout << C(5, 2) << endl; // 从 5 个里选 2 个，共 10 种
    return 0;
}
